{
  "story": "Merge sort divides the collection into single items, then repeatedly merges sorted pairs until the entire array is fully ordered.",
  "aha": {
    "stateId": "merge",
    "observation": "Combining two sorted halves creates a single larger sorted sequence."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Divide", "Subdivide", "Merge", "Complete"]
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Merge Sort",
        "regions": [
          {
            "id": "left",
            "label": "Left Subarray",
            "values": ["3", "1"]
          },
          {
            "id": "right",
            "label": "Right Subarray",
            "values": ["4", "2"]
          }
        ],
        "states": [
          {
            "id": "divide",
            "label": "Divide",
            "short": "Split",
            "sentence": "The array is split in half.",
            "why": "Splitting reduces the problem into smaller independent pieces.",
            "active": ["3", "1"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "size",
                "label": "Chunk Size",
                "value": "2"
              }
            ]
          },
          {
            "id": "subdivide",
            "label": "Subdivide",
            "short": "Base",
            "sentence": "Each item becomes a single-element list.",
            "why": "Single-element lists are trivially sorted.",
            "active": ["3"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "size",
                "label": "Chunk Size",
                "value": "1"
              }
            ]
          },
          {
            "id": "merge",
            "label": "Merge",
            "short": "Combine",
            "sentence": "Sorted halves are merged together.",
            "why": "Merging maintains sorted order efficiently.",
            "active": ["1", "3", "2", "4"],
            "calloutRegion": "right",
            "readouts": [
              {
                "id": "size",
                "label": "Chunk Size",
                "value": "4"
              }
            ]
          },
          {
            "id": "complete",
            "label": "Complete",
            "short": "Done",
            "sentence": "The array is fully sorted.",
            "why": "All parts have been combined.",
            "active": ["1", "2", "3", "4"],
            "calloutRegion": "right",
            "readouts": [
              {
                "id": "size",
                "label": "Chunk Size",
                "value": "4"
              }
            ]
          }
        ]
      }
    ]
  }
}
